package it.cdanet.cpeconfigurator

import androidx.compose.ui.graphics.toArgb
import it.cdanet.cpeconfigurator.ui.ConsolePalette
import it.cdanet.cpeconfigurator.ui.ConsoleTokens
import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assume.assumeTrue
import org.junit.Test

/**
 * The app wears the colours of the console: ConsoleTokens.kt (generated by
 * android/tools/console-tokens.mjs) must match console/src/styles/tokens.css.
 */
class ConsoleTokensTest {
    private val css = listOf("../../console/src/styles/tokens.css", "../console/src/styles/tokens.css").map(::File).firstOrNull { it.exists() }

    /** The custom properties of the block that starts with [selector]. */
    private fun block(text: String, selector: String): Map<String, String> {
        val start = text.indexOf("$selector {")
        check(start >= 0) { "$selector not in tokens.css" }
        val body = text.substring(start, text.indexOf('}', start))
        return Regex("--([a-z0-9-]+):\\s*([^;]+);").findAll(body).associate { it.groupValues[1] to it.groupValues[2].trim() }
    }

    private fun hex(c: androidx.compose.ui.graphics.Color) = "#%06x".format(c.toArgb() and 0xFFFFFF)

    private fun same(palette: ConsolePalette, tokens: Map<String, String>) {
        val app = mapOf(
            "brand" to palette.brand, "brand-ink" to palette.brandInk, "brand-soft" to palette.brandSoft,
            "bg" to palette.bg, "surface" to palette.surface, "surface-2" to palette.surface2, "surface-3" to palette.surface3,
            "line" to palette.line, "line-strong" to palette.lineStrong, "ink" to palette.ink, "muted" to palette.muted,
            "good" to palette.good, "good-bg" to palette.goodBg, "warn" to palette.warn, "warn-bg" to palette.warnBg,
            "bad" to palette.bad, "bad-bg" to palette.badBg, "info" to palette.info, "info-bg" to palette.infoBg,
        )
        for ((name, color) in app) assertEquals("--$name: run node android/tools/console-tokens.mjs", tokens[name]?.lowercase(), hex(color))
    }

    @Test
    fun appColoursAreTheConsoleTokens() {
        assumeTrue("console/ not in this checkout", css != null)
        val text = css!!.readText()
        val light = block(text, ":root")
        same(ConsoleTokens.Light, light)
        same(ConsoleTokens.Dark, light + block(text, ":root[data-theme='dark']"))
        assertEquals(light["radius-sm"], "${ConsoleTokens.RADIUS_SM}px")
        assertEquals(light["radius"], "${ConsoleTokens.RADIUS}px")
        assertEquals(light["radius-lg"], "${ConsoleTokens.RADIUS_LG}px")
    }
}
